// A rough cut to refine: the first seconds of speech in every clip that has any, when the cut starts empty.
const roughCut = (t) => t.setValues({ picks: t.getValues().clips.filter((k) => k.speech).map((k) => ({ clip: k.key, start: k.speech.start, end: Math.min(k.speech.end, k.speech.start + 6) })) }, 'Rough cut');
t3template.addToolbarButton('Rough Cut', roughCut, { shortcut: 'shift+r' });
if (!t3template.getValues().picks.length && !t3template.getValues().suggestions.length) roughCut(t3template);
t3template.addControl({ id: 'voice', label: 'Voice Polish', type: 'toggle', default: true, panel: 'Finish' });
t3template.addControl({ id: 'name', label: 'Lower Third', type: 'text', default: 'Founder Lessons', panel: 'Finish' });
t3template.addControl({ id: 'nameSec', label: 'Title (s)', type: 'slider', min: 0, max: 8, step: 0.5, default: 3, panel: 'Finish' });
// Sound: heard on the program monitor and rendered by ffmpeg on the whole cut.
t3template.addAudioFilter('voice', (c) => (c.voice ? [{ type: 'highpass', frequency: 90 }, { type: 'compressor', threshold: -22, ratio: 3, makeup: 4 }] : null));
// A lower third over the first seconds, drawn at the output size.
t3template.addOverlay('lower-third', ({ context, width, height }, c) => {
  const h = Math.round(height * 0.07);
  context.fillStyle = 'rgba(0, 0, 0, 0.6)';
  context.fillRect(0, height * 0.78, width, h);
  context.fillStyle = '#ffffff';
  context.font = `600 ${Math.round(h * 0.5)}px sans-serif`;
  context.textBaseline = 'middle';
  context.fillText(c.name, width * 0.06, height * 0.78 + h / 2);
}, (c) => (c.name && c.nameSec ? { start: 0, end: c.nameSec } : null));
// Keep only short suggestions: accept the pending ones under 8 seconds in one undo step.
t3template.addToolbarButton('Accept Short', (t) => {
  const ids = t.getValues().suggestions.filter((s) => s.status === 'pending' && s.end - s.start < 8).map((s) => s.id);
  return t.setValues({ accept: ids }, 'Accept short suggestions');
}, { shortcut: 'shift+s' });
// Export drops picks shorter than a second (the cut on screen keeps them).
t3template.addEdlTransform((edl) => {
  edl.tracks[0].clips = edl.tracks[0].clips.filter((k) => k.duration >= 1);
  return edl;
});
